window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2827b49acd074d83"]={"versions": [{"id": "FIG-2827b49acd074d83", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd GPT Activation</code>) im Kontext der AUTOSAR Classic Platform (SWS Watchdog Manager). Das Diagramm spezifiziert die zyklische Triggerung und Überwachung des Watchdogs über eine timergesteuerte Benachrichtigung (General Purpose Timer, GPT) im Zusammenwirken zwischen Hardware-Treiberschicht, Watchdog-Abstraktionsschicht und Service-Schicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien (von links nach rechts):</p>\n<ul class=\"fig-list\">\n<li><code>Timer Hardware</code>: Hardware-Timerkomponente.</li>\n<li><code>:Gpt</code>: AUTOSAR GPT-Treiber (MCAL).</li>\n<li><code>:WdgM</code>: AUTOSAR Watchdog Manager (Service Layer).</li>\n<li><code>:WdgIf</code>: AUTOSAR Watchdog Interface (ECU Abstraction Layer).</li>\n<li><code>:Wdg</code>: AUTOSAR Watchdog Driver (MCAL).</li>\n<li><code>Watchdog Hardware</code>: Physikalische Watchdog-Hardwareperipherie.</li>\n</ul>\n<p class=\"fig-p\">Verwendete Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>Interrupt</code>: Hardware-Interrupt von <code>Timer Hardware</code> an <code>:Gpt</code>.</li>\n<li><code>WdgM_Cbk_GptNotification()</code>: Callback-Aufruf von <code>:Gpt</code> an <code>:WdgM</code>.</li>\n<li><code>Check Alive Counters</code>: Interner Funktionsaufruf/Selbstaufruf auf <code>:WdgM</code>.</li>\n<li><code>WdgIf_Trigger(DeviceIndex)</code>: Synchroner Funktionsaufruf von <code>:WdgM</code> an <code>:WdgIf</code> mit Geräteindex als Parameter.</li>\n<li><code>Wdg_Trigger()</code>: Synchroner Funktionsaufruf von <code>:WdgIf</code> an den treiberspezifischen Watchdog <code>:Wdg</code>.</li>\n<li><code>Trigger Hardware</code>: Hardware-Triggerimpuls von <code>:Wdg</code> an <code>Watchdog Hardware</code>.</li>\n<li>Entsprechende synchrone Rücksprungpfeile (gestrichelt) von <code>Watchdog Hardware</code>, <code>:Wdg</code>, <code>:WdgIf</code> und <code>:WdgM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>Timer Hardware</code> generiert einen zyklischen <code>Interrupt</code> an den <code>:Gpt</code>-Treiber.</li>\n<li>Der <code>:Gpt</code>-Treiber leitet das Ereignis über den Callback <code>WdgM_Cbk_GptNotification()</code> an den Watchdog Manager (<code>:WdgM</code>) weiter.</li>\n<li>Der <code>:WdgM</code> führt eine interne Prüfung der Alive-Zähler durch (<code>Check Alive Counters</code>).</li>\n<li>Es folgt ein bedingter Block (<code>alt Check Global Supervision Status</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[else]</code>: Ist der globale Überwachungsstatus nicht gestoppt, ruft <code>:WdgM</code> <code>WdgIf_Trigger(DeviceIndex)</code> auf. Das <code>:WdgIf</code> delegiert diesen Aufruf via <code>Wdg_Trigger()</code> an den spezifischen Treiber <code>:Wdg</code>, welcher über <code>Trigger Hardware</code> die physikalische <code>Watchdog Hardware</code> nachtriggert. Nach Abarbeitung kehren die synchronen Aufrufe sukzessive zurück.</li>\n<li>Zweig <code>[WDGM_ALIVE_STOPPED]</code>: Ist die Alive-Überwachung gestoppt bzw. fehlgeschlagen, unterbleibt der Triggeraufruf an <code>:WdgIf</code>; es erfolgt kein Nachtriggern der Hardware.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss kehrt über die Rücksprungnachricht von <code>:WdgM</code> zu <code>:Gpt</code> und schließlich zur <code>Timer Hardware</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert den normativen Steuerungsablauf für die GPT-basierte Ausführung der Watchdog-Manager-Hauptfunktionalität. Entwickler und Integratoren müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\">\n<li>der GPT-Kanal für den Aufruf des Callbacks <code>WdgM_Cbk_GptNotification()</code> passend konfiguriert ist;</li>\n<li>die Überprüfung der Alive-Zähler vor dem Absetzen des Hardware-Triggers stattfindet;</li>\n<li>im Zustand <code>WDGM_ALIVE_STOPPED</code> die Ausführung von <code>WdgIf_Trigger(DeviceIndex)</code> strikt unterdrückt wird, damit der Hardware-Watchdog auslöst (ECU-Reset);</li>\n<li>die Durchlaufzeiten des gesamten Strangs von Callback bis Hardwaretrigger innerhalb der maximal zulässigen Watchdog-Triggerperiode liegen.</li>\n</ul>"}, {"id": "FIG-5f6d1c6a84c34890", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd WdgM_GPT Activation</code>) im Kontext der AUTOSAR Classic Platform (SWS Watchdog Manager). Das Diagramm spezifiziert die zyklische Triggerung und Überwachung des Watchdogs über eine timergesteuerte Benachrichtigung (General Purpose Timer, GPT) im Zusammenwirken zwischen Hardware-Treiberschicht, Watchdog-Abstraktionsschicht und Service-Schicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien (von links nach rechts):</p>\n<ul class=\"fig-list\">\n<li><code>Timer Hardware</code>: Hardware-Timerkomponente.</li>\n<li><code>:Gpt</code>: AUTOSAR GPT-Treiber (MCAL).</li>\n<li><code>:WdgM</code>: AUTOSAR Watchdog Manager (Service Layer).</li>\n<li><code>:WdgIf</code>: AUTOSAR Watchdog Interface (ECU Abstraction Layer).</li>\n<li><code>:Wdg</code>: AUTOSAR Watchdog Driver (MCAL).</li>\n<li><code>Watchdog Hardware</code>: Physikalische Watchdog-Hardwareperipherie.</li>\n</ul>\n<p class=\"fig-p\">Verwendete Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>Interrupt()</code>: Hardware-Interrupt von <code>Timer Hardware</code> an <code>:Gpt</code>.</li>\n<li><code>WdgM_Cbk_GptNotification()</code>: Callback-Aufruf von <code>:Gpt</code> an <code>:WdgM</code>.</li>\n<li><code>Check Alive Counters()</code>: Interner Funktionsaufruf/Selbstaufruf auf <code>:WdgM</code>.</li>\n<li><code>WdgIf_Trigger(uint8)</code>: Synchroner Funktionsaufruf von <code>:WdgM</code> an <code>:WdgIf</code> mit einem Parameter vom Typ <code>uint8</code>.</li>\n<li><code>Wdg_Trigger()</code>: Synchroner Funktionsaufruf von <code>:WdgIf</code> an den treiberspezifischen Watchdog <code>:Wdg</code>.</li>\n<li><code>Trigger Hardware()</code>: Hardware-Triggerimpuls von <code>:Wdg</code> an <code>Watchdog Hardware</code>.</li>\n<li>Entsprechende synchrone Rücksprungpfeile (gestrichelt) von <code>Watchdog Hardware</code>, <code>:Wdg</code>, <code>:WdgIf</code> und <code>:WdgM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>Timer Hardware</code> generiert einen zyklischen <code>Interrupt()</code> an den <code>:Gpt</code>-Treiber.</li>\n<li>Der <code>:Gpt</code>-Treiber leitet das Ereignis über den Callback <code>WdgM_Cbk_GptNotification()</code> an den Watchdog Manager (<code>:WdgM</code>) weiter.</li>\n<li>Der <code>:WdgM</code> führt eine interne Prüfung der Alive-Zähler durch (<code>Check Alive Counters()</code>).</li>\n<li>Es folgt ein bedingter Block (<code>alt Check Global Supervision Status</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[else]</code>: Ist der globale Überwachungsstatus nicht gestoppt, ruft <code>:WdgM</code> <code>WdgIf_Trigger(uint8)</code> auf. Das <code>:WdgIf</code> delegiert diesen Aufruf via <code>Wdg_Trigger()</code> an den spezifischen Treiber <code>:Wdg</code>, welcher über <code>Trigger Hardware()</code> die physikalische <code>Watchdog Hardware</code> nachtriggert. Nach Abarbeitung kehren die synchronen Aufrufe sukzessive zurück.</li>\n<li>Zweig <code>[WDGM_ALIVE_STOPPED]</code>: Ist die Alive-Überwachung gestoppt bzw. fehlgeschlagen, unterbleibt der Triggeraufruf an <code>:WdgIf</code>; es erfolgt kein Nachtriggern der Hardware.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss kehrt über die Rücksprungnachricht von <code>:WdgM</code> zu <code>:Gpt</code> und schließlich zur <code>Timer Hardware</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert den normativen Steuerungsablauf für die GPT-basierte Ausführung der Watchdog-Manager-Hauptfunktionalität. Entwickler und Integratoren müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\">\n<li>der GPT-Kanal für den Aufruf des Callbacks <code>WdgM_Cbk_GptNotification()</code> passend konfiguriert ist;</li>\n<li>die Überprüfung der Alive-Zähler vor dem Absetzen des Hardware-Triggers stattfindet;</li>\n<li>im Zustand <code>WDGM_ALIVE_STOPPED</code> die Ausführung von <code>WdgIf_Trigger(uint8)</code> strikt unterdrückt wird, damit der Hardware-Watchdog auslöst (ECU-Reset);</li>\n<li>die Durchlaufzeiten des gesamten Strangs von Callback bis Hardwaretrigger innerhalb der maximal zulässigen Watchdog-Triggerperiode liegen.</li>\n</ul>"}], "trans": [{"from": "FIG-2827b49acd074d83", "to": "FIG-5f6d1c6a84c34890", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Sequenzbezeichner: Im Diagrammkopf von <code>sd GPT Activation</code> zu <code>sd WdgM_GPT Activation</code> präzisiert.</li>\n<li>Aufruf <code>WdgIf_Trigger</code>: Parametersignatur von formalem Parameternamen <code>DeviceIndex</code> auf konkreten AUTOSAR-Basistyp <code>uint8</code> geändert.</li>\n<li>Methoden- und Signalaufrufe: <code>Interrupt</code>, <code>Check Alive Counters</code> und <code>Trigger Hardware</code> wurden redaktionell durch Ergänzung expliziter Klammern als <code>Interrupt()</code>, <code>Check Alive Counters()</code> und <code>Trigger Hardware()</code> typisiert.</li>\n</ul>"}]};
